 try:
  s=urllib.request.urlopen(f\"https://energy.suda.edu.cn/9469/list{n}.htm\",timeout=15).read().decode(\"utf-8\")
  links=re.findall(r\"<a["'^>]+href=['"\\\"\\x27](["'^'"\\\"\\x27]+)[\\\"\\x27]["'^>]*>(.*?)</a>",s,re.S)
  return (n,[(u,re.sub("<[''^>]*>","",t).strip()) for u,t in links if "2024" in t or "2025" in t])
 except Exception as e: return (n,str(e))
for result in concurrent.futures.ThreadPoolExecutor().map(f,[9,10,11,12,13,14,15]): print(result)'"'"

